-- #################
--- AUTOSTART ---
-- #################

-- Environment variables to force dark theme in GTK apps and disable portal theming
-- hl.env("GTK_THEME", "adw-gtk3-dark")
hl.env("ADW_DISABLE_PORTAL", "1")

-- --- FORCE INTEGRATED GRAPHICS (BATTERY) ---
hl.env("AQ_DRM_DEVICES", "/dev/dri/card2:/dev/dri/card1")
hl.env("WLR_DRM_DEVICES", "/dev/dri/card2:/dev/dri/card1")

hl.env("QT_QPA_PLATFORMTHEME", "qt5ct")

hl.on("hyprland.start", function ()
    -- Startup commands to ensure the system knows we prefer dark theme
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme 'prefer-dark'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme 'adw-gtk3-dark'")

    -- Startup commands to launch background services and applications
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("~/.config/hypr/scripts/power_mode.sh")
    hl.exec_cmd("~/.config/quickshell/scripts/backend_daemon.sh")
    hl.exec_cmd("python3 -m compileall -q ~/.config/quickshell/scripts/")
    hl.exec_cmd("python3 ~/.config/quickshell/scripts/app_usage_daemon.py")
    hl.exec_cmd("quickshell")
    -- hl.exec_cmd("qs -c overview")
    hl.exec_cmd("qs -p ~/.config/quickshell/overview")

    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)

