-- Confirm and close on ALT release (works for both Left Alt and Right Alt)
-- NOTE: "release = true, transparent = true" is the closest translation of the
-- r (release) + t (transparent) flags from "bindrt"; double-check against the
-- hl.bind reference if your version uses different field names for these flags.
hl.bind("ALT + Alt_L", hl.dsp.exec_cmd("qs ipc -p ~/.config/quickshell call alttab commit"), { release = true, transparent = true })
hl.bind("ALT + Alt_R", hl.dsp.exec_cmd("qs ipc -p ~/.config/quickshell call alttab commit"), { release = true, transparent = true })

